-- 8.6 의 순위 쿼리를 완성한다

public interface TeamRank {
    String getTeamName();
    String getUsername();
    int getAge();
    int getAgeRank();
}

@Query(value = """
        select
            t.name     as teamName,
            m.username as username,
            m.age      as age,
            rank() over (partition by t.team_id order by m.age desc)
                       as ageRank
        from member m
        join team t on t.team_id = m.team_id
        where m.age >= :minAge
        """, nativeQuery = true)
List<TeamRank> rankByTeam(@Param("minAge") int minAge);

@Test
@Transactional
void 순위() {
    em.clear();
    for (TeamRank r : memberRepository.rankByTeam(10)) {
        System.out.printf("%-8s %-6s %2d %d위%n",
                r.getTeamName(), r.getUsername(), r.getAge(), r.getAgeRank());
    }
}

