-- JdbcClient 와 나란히 둔다

@Repository
@RequiredArgsConstructor
public class MemberJdbcRepository {

    private final JdbcClient jdbc;

    public List<TeamRankDto> rankByTeam(int minAge) {
        return jdbc.sql("""
                select
                    t.name     as team_name,
                    m.username as username,
                    m.age      as age,
                    rank() over (partition by t.team_id order by m.age desc)
                               as age_rank
                from member m
                join team t on t.team_id = m.team_id
                where m.age >= :minAge
                """)
            .param("minAge", minAge)
            .query(TeamRankDto.class)
            .list();
    }
}

@Test
void jdbc() {
    memberJdbcRepository.rankByTeam(10)
            .forEach(System.out::println);
}

